def tdict2(lang):
    d=tdict(lang); g=dict(G2[lang])
    g['hl']=''.join(f'<li>{x}</li>' for x in g['hl'])
    d.update(g)
    for t in TOURS:
        ex=EXTRA_T.get(t['id'])
        if not ex: continue
        k=t['k']
        d[k+'_st']=''.join(f'<li data-day="{i+1}"><b>{a}</b><p>{b}</p><span class="dmeta"><span>{g[ex["meta"][i][0]]}</span><span>{g[ex["meta"][i][1]]}</span></span></li>' for i,(a,b) in enumerate(t['steps'][lang]))
    return d

