_tdict2_old=tdict2
def tdict2(lang):
    d=_tdict2_old(lang)
    for tid,tx in TXT_T.items():
        t=next(x for x in TOURS if x['id']==tid); k=t['k']; L=dict(tx[lang])
        hl=L.pop('hl'); meta=L.pop('meta')
        for kk in [x for x in list(L) if x.startswith('mp_d')]: L[k+'_'+kk]=L.pop(kk)
        d.update(L); d[k+'_hl']=''.join(f'<li>{x}</li>' for x in hl)
        d[k+'_st']=''.join(f'<li data-day="{i+1}"><b>{a}</b><p>{b}</p><span class="dmeta"><span>{meta[i][0]}</span><span>{meta[i][1]}</span></span></li>' for i,(a,b) in enumerate(t['steps'][lang]))
    return d

