# ================= TANGIER 4: 4 days Tangier → Chefchaouen → Fes → Merzouga → Marrakech =================
def _shift_steps(src, start, fesfix=True):
    rep={'en':('Morning pick-up in Fes and drive','After breakfast we leave Fes and drive'),'es':('Recogida por la mañana en Fez y ruta','Tras el desayuno salimos de Fez en ruta'),'fr':('Départ le matin de Fès vers','Après le petit-déjeuner, départ de Fès vers'),'it':('Partenza al mattino da Fes verso','Dopo colazione partenza da Fes verso')}
    out={}
    for l,lst in src.items():
        new=[]
        for i,(t,b) in enumerate(lst):
            w,_,rest=t.partition(' ')
            num,_,rest2=rest.partition(' ')
            t2=f"{w} {int(num)+start-1} {rest2}"
            if i==0 and fesfix: b=b.replace(*rep[l])
            new.append((t2,b))
        out[l]=new
    return out
