# ---- move Included / Not included below the itinerary ----
import re as _re2
def _blk(h,start):
    d=0
    for m in _re2.finditer(r'<(/?)div\b',h[start:]):
        d+= -1 if m.group(1) else 1
        if d==0: return start+h[start:].index('>',m.start())+1
    return -1
_main2_inc=main2
def main2(t):
    h=_main2_inc(t)
    a=h.find('<div class="ad-two">'); b=h.find('<div class="itin')
    if a<0 or b<0 or b<a: return h
    ae=_blk(h,a); be=_blk(h,b)
    if ae<0 or be<0: return h
    two=h[a:ae]
    h=h[:a]+h[ae:be]+'\n      '+two.replace('<div class="ad-two">','<div class="ad-two ad-after">',1)+h[be:]
    return h
CSS2+='\n.ad-two.ad-after{margin-top:44px}\n'

