_PDT={'en':dict(pd_e="Keep exploring",pd_h="Popular <em>Destinations</em>",pd_p="Other private journeys our travellers love.",pd_v="View tour",pd_d="days",pd_d1="day",pd_all="All tours"),
 'es':dict(pd_e="Sigue explorando",pd_h="Destinos <em>populares</em>",pd_p="Otros viajes privados que encantan a nuestros viajeros.",pd_v="Ver circuito",pd_d="días",pd_d1="día",pd_all="Todos los circuitos"),
 'fr':dict(pd_e="Continuez l’exploration",pd_h="Destinations <em>populaires</em>",pd_p="D’autres voyages privés que nos voyageurs adorent.",pd_v="Voir le circuit",pd_d="jours",pd_d1="jour",pd_all="Tous les circuits"),
 'it':dict(pd_e="Continua a esplorare",pd_h="Destinazioni <em>popolari</em>",pd_p="Altri viaggi privati amati dai nostri viaggiatori.",pd_v="Vedi il tour",pd_d="giorni",pd_d1="giorno",pd_all="Tutti i tour")}
_tdict2_pd=tdict2
def tdict2(lang):
    d=_tdict2_pd(lang); d.update(_PDT[lang])
    for t in TOURS: d['pdt_'+t['k']]=t['t'][lang]; d['pdr_'+t['k']]=t['route'][lang]
    return d
def _pd_pick(t):
    same=[x for x in TOURS if x['city']==t['city'] and x['id']!=t['id']]
    if t.get('dtrip'): pool=same
    else:
        near=sorted(same,key=lambda x:abs(x['days']-t['days']))
        others=[x for x in TOURS if x['city'] not in(t['city'],'daytrip') and x['id']!=t['id']]
        others=sorted(others,key=lambda x:(abs(x['days']-t['days']),x['id']))
        pool=near[:2]+others
    if t.get('dtrip'): pool=sorted(pool,key=lambda x:(x['start']['en']!=t['start']['en'],x['id']))
    seen=[];[seen.append(x) for x in pool if x not in seen]
    out=[];imgs=set()
    for x in seen:
        im=EXTRA_T.get(x['id'],{}).get('hero_src',('',))[0]
        if im in imgs: continue
        out.append(x);imgs.add(im)
        if len(out)==3: break
    for x in seen:
        if len(out)==3: break
        if x not in out: out.append(x)
    return out
def _pd_html(t):
    cards=''
    for x in _pd_pick(t):
        img=EXTRA_T.get(x['id'],{}).get('hero_src',('{{HERO}}',))[0]
        cards+=(f'<a class="pd-c reveal" href="{x["id"]}.html"><span class="pd-i"><img src="{img}" alt="" loading="lazy">'
                f'<span class="pd-dd"><b>{x["days"]}</b> <span data-i="{"pd_d1" if x["days"]==1 else "pd_d"}">days</span></span></span>'
                f'<span class="pd-b"><b data-i="pdt_{x["k"]}">x</b><small data-i="pdr_{x["k"]}">x</small><span class="pd-l"><span data-i="pd_v">View tour</span><svg><use href="#i-arrow"/></svg></span></span></a>')
    return f'''<section class="pd">
  <div class="in">
    <div class="pd-head reveal"><span class="eyebrow" data-i="pd_e">Keep exploring</span><h2 data-i="pd_h">Popular Destinations</h2>
      <svg class="pd-ul" viewBox="0 0 300 24" aria-hidden="true"><path class="u1" d="M6 15 C70 4 120 20 170 11 S262 5 294 13" pathLength="1"/><path class="u2" d="M40 20 C110 14 190 22 262 17" pathLength="1"/></svg>
      <p data-i="pd_p">x</p></div>
    <div class="pd-grid">{cards}</div>
    <div class="pd-more"><a class="pd-all" href="index.html#tours"><span data-i="pd_all">All tours</span><svg><use href="#i-arrow"/></svg></a></div>
  </div>
</section>
'''
_main2_pd=main2
def main2(t):
    h=_main2_pd(t); i=h.rfind('<footer')
    return h if i<0 else h[:i]+_pd_html(t)+h[i:]
